        if (supports_streaming) flags_v |= (1u << 1);
        if (nosound) flags_v |= (1u << 3);
        if (preload_prefix_size.has_value()) flags_v |= (1u << 2);
        if (video_start_ts.has_value()) flags_v |= (1u << 4);
        if (video_codec.has_value()) flags_v |= (1u << 5);
